    "pub_date": "2026-08-17 05:58:23",
    "author": "许正 叶挺",
    "description": "新华社哈拉雷8月16日电（记者许正 叶挺）津巴布韦警方16日发表声明说，该国北部卡里巴湖11日发生的船只倾覆事故死亡人数已升至84人。 据悉，事故发生后已有77人获救。警方表示，目前仍有人员失踪，搜寻工作仍在继续。 11日下午，该船只在卡里巴湖上行驶时发生倾覆。据津巴布韦《先驱报》报道，事故船只遭遇强风天气。 津巴布韦总统姆南加古瓦12日宣布该起事故为“国家灾难”，并责令相关部门为遇难者家属提供必要帮助。 卡里巴湖位于津巴布韦和赞比亚交…",
    "content": "新华社哈拉雷8月16日电（记者许正 叶挺）津巴布韦警方16日发表声明说，该国北部卡里巴湖11日发生的船只倾覆事故死亡人数已升至84人。 据悉，事故发生后已有77人获救。警方表示，目前仍有人员失踪，搜寻工作仍在继续。 11日下午，该船只在卡里巴湖上行驶时发生倾覆。据津巴布韦《先驱报》报道，事故船只遭遇强风天气。 津巴布韦总统姆南加古瓦12日宣布该起事故为“国家灾难”，并责令相关部门为遇难者家属提供必要帮助。 卡里巴湖位于津巴布韦和赞比亚交界处，拥有丰富的水电和渔业资源。长期以来，湖区居民依靠湖上船运往返于偏远渔业社区…"
