    "content": "美国总统特朗普（资料图） 当地时间8月16日，美国总统特朗普在其社交媒体平台“真实社交”上发文，对沙特阿拉伯、土耳其和巴基斯坦近期签署共同防务协议表示欢迎。 特朗普表示，这一协议表明中东地区正在加强团结，各国将能够以“更加切实有效的方式”保卫自身。他同时向沙特、土耳其和巴基斯坦三国领导人表示祝贺，并称这一协议是“大胆而重要的第一步”。 当地时间8月7日，土耳其总统埃尔多安、巴基斯坦总理夏巴兹访问沙特并同沙特王储兼首相穆罕默德举行联合防务会议，三方签署联合防务协议。 该协议旨在增强针对任何侵略行为的集体威慑力，并规定…"
