    "content": "当地时间7月23日，2026年国际数学家大会在美国费城开幕，现场揭晓2026年菲尔兹奖得主，中国青年数学家邓煜、王虹双双获奖。菲尔兹奖由国际数学联盟颁发，是数学界最高荣誉之一，每四年颁发一次，每次获奖者不超过四位，以奖励当年未满40岁、在数学领域做出杰出贡献的学者。 此前，获得该奖项的华裔数学家仅有丘成桐、陶哲轩，他们的教育与学术训练主要在海外展开；而邓煜、王虹两人都曾是北京大学的本科生，他们的获奖被看作是中国数学教育的重要时刻。 在菲尔兹奖揭晓后，记者以网络连线的方式对邓煜进行了专访，37岁的他现任美国芝加哥大学…"
