    "content": "据巴西里约热内卢州消防部门16日确认，当日凌晨，该州彼得罗波利斯市附近发生一起旅游大巴翻车事故，已造成至少10人死亡。 新华社里约热内卢8月16日电（记者赵焱）据巴西里约热内卢州消防部门16日确认，当日凌晨，该州彼得罗波利斯市附近发生一起旅游大巴翻车事故，已造成至少10人死亡。 消防部门发表的公报说，事故发生在当地时间凌晨4时30分左右，这辆载有数十名游客的巴士从彼得罗波利斯附近山区下山时发生侧翻。消防人员接到事故报告抵达现场后发现8人遇难，他们将受伤者送往附近几所医院，有两人因伤势过重不治身亡。遇难者中包括8名妇…"
