    "description": "从大学时期就一直想做查单词/背单词的网站。 甚至我还搜集过单词库，还注册过域名。 但是各种原因一直没做。 现在 AI 时代，生产力大爆发，搞了几天终于搞出来了。 以前的单词网站是固定词库，词库有，就能查，没有就查不到。 核心在词库。 我的新网站很简单，不管你输入什么，我都用 ai 按格式生成解释。 这样就不用词库了，而且可以做多语言对多语言的翻译。 欢迎大家来体验一下：Dict.Cat 词猫 用的模型是 doubao-seed-2.0-…",
