    "description": "DeepSeek Harness （ dsh ）刚开源没几天，GitHub 上线一天就冲上几万星，「一切皆插件」刷屏。这几天我在社区里逛了一圈：插件市场、Awesome 列表、桌面壳，全冒出来了。但它们解决的都是同一件事——帮你找插件。装完插件之后呢？你还得手写 YAML ，才能把这些 skill 、工具、事件钩子组装成一个真正能用的 Agent 。 我给它补上了缺的这一环：一个插件编排扩展，把「组装 Agent 」从写配置，变成画布上…",
