    "title": "[厦门] 软件园二期北门那家沙县小吃，是不是又涨价了。",
    "link": "https://www.v2ex.com/t/1234801#reply6",
    "pub_date": "2026-08-16 22:16:33",
    "author": "xiaohongt3",
    "description": "刚毕业那年在观日路附近租房，每天挤 32 路挤到爱琴海站下车，再走十分钟到软件园，路上碰到的十有八九也是程序员，工牌都不摘就往公司赶。那时候园区里到处是奶茶店和沙县，中午高峰期电梯要等三趟。加班到晚上九十点，走出楼下能看到隔壁楼层还有一半的灯亮着，也不知道是心理安慰还是真的。 现在早就不在软件园上班了，但偶尔路过还是会习惯性抬头看看以前工位那层灯亮不亮。 厦门的老程序员，谁还记得软件园二期哪个门口的煎饼摊最好吃，评论区聊聊呗。",
    "content": "刚毕业那年在观日路附近租房，每天挤 32 路挤到爱琴海站下车，再走十分钟到软件园，路上碰到的十有八九也是程序员，工牌都不摘就往公司赶。那时候园区里到处是奶茶店和沙县，中午高峰期电梯要等三趟。加班到晚上九十点，走出楼下能看到隔壁楼层还有一半的灯亮着，也不知道是心理安慰还是真的。 现在早就不在软件园上班了，但偶尔路过还是会习惯性抬头看看以前工位那层灯亮不亮。 厦门的老程序员，谁还记得软件园二期哪个门口的煎饼摊最好吃，评论区聊聊呗。"
