    "content": "IT之家 8 月 16 日消息，印度总理 Narendra Modi（纳伦德拉 · 莫迪）在当地时间昨日发表的印度独立日演讲中表示， 未来 7~8 年将有 5~8 座半导体工厂在该国投运 。 莫迪表示，印度已开始建立自己的半导体制造能力，以实现自给自足。印度目前已有三家大型半导体工厂投入运营。 IT之家注意到，这位印度总理在演讲中提到，该国 目标到 2047 年建设 100GW 的核电装机容量 、 推动“印度制造”6G 技术覆盖全世界 ；此外印度需要扩大在制造业全价值链的存在并提升生产质量。"
