    "content": "（来源：麻省理工科技评论） 今年夏天，北半球多地遭遇罕见高温。欧洲刚刚经历了有记录以来最热的 6 月和 7 月，美国本土 48 州则在 7 月刷新了单月最高温纪录，韩国也测得历史最高气温。 但这一轮高温可能还没有到头。一些科学家已经开始把目光投向 2027 年。原因是，今年形成的厄尔尼诺仍在发展，它对全球气温最明显的影响，很可能要到明年才真正显现。 那么，今年夏天为什么会这么热？明年又会发生什么？我们该如何提前应对？ 首先，最直接的背景仍然是气候变化。随着人类持续燃烧煤炭、石油和天然气，大量温室气体进入大气，全球气…"
