    "description": "新华社北京8月16日电 综合新华社驻外记者报道：在日本宣布无条件投降81周年之际，日本首相高市早苗15日以“自民党总裁”身份，向供奉有二战甲级战犯的靖国神社供奉“玉串料”（祭祀费），并在出席日本政府举办的“全国战殁者追悼仪式”前从会场停车场朝靖国神社所在方向“遥拜”。此外，日本防卫大臣小泉进次郎等多名政客分别前往靖国神社参拜，这是日本连续第7年有现任阁僚在这一天参拜靖国神社。日方错误行径引发国际社会和日本国内爱好和平人士强烈反对。",
    "content": "新华社北京8月16日电 综合新华社驻外记者报道：在日本宣布无条件投降81周年之际，日本首相高市早苗15日以“自民党总裁”身份，向供奉有二战甲级战犯的靖国神社供奉“玉串料”（祭祀费），并在出席日本政府举办的“全国战殁者追悼仪式”前从会场停车场朝靖国神社所在方向“遥拜”。此外，日本防卫大臣小泉进次郎等多名政客分别前往靖国神社参拜，这是日本连续第7年有现任阁僚在这一天参拜靖国神社。日方错误行径引发国际社会和日本国内爱好和平人士强烈反对。"
