    "content": "新华社基辅8月16日电（记者李东旭）乌克兰军方16日称，俄军15日晚至16日凌晨使用导弹和无人机对乌多地发动空袭，乌军当天打击俄军“棱堡”导弹系统，造成装备和人员损失。 乌克兰空军当天在社交媒体发文称，俄军从库尔斯克州、布良斯克州、沃罗涅日州、别尔哥罗德州等地向乌境内发射多型导弹和106架无人机，袭击目标主要位于基辅、波尔塔瓦州、第聂伯罗彼得罗夫斯克州等地。乌境内13处地点被导弹或无人机击中，另有3处地点被导弹或无人机碎片击中。 乌空军称，截至16日上午8时，乌防空火力和电子战部队拦截了3枚巡航导弹和85架无人机。…"
