    "description": "8月9日是日本长崎遭原子弹轰炸81周年纪念日。在日本长崎原子弹爆炸中心地东南方向约150米处，坐落着长崎核爆资料馆。这些天，资料馆人流不断。 在该馆第三展厅，“日中战争和太平洋战争”巨幅年表梳理了1931年到1945年的历史脉络。“1937年”一列，写有“12月，占领南京，发生大屠杀事件”，并配有日军在南京盘查逃难中国百姓的照片。 然而，该馆7月28日公布的新展陈解说文本方案显示，有关“南京大屠杀”的表述从明年3月起将改为“南京事件”。…",
    "content": "8月9日是日本长崎遭原子弹轰炸81周年纪念日。在日本长崎原子弹爆炸中心地东南方向约150米处，坐落着长崎核爆资料馆。这些天，资料馆人流不断。 在该馆第三展厅，“日中战争和太平洋战争”巨幅年表梳理了1931年到1945年的历史脉络。“1937年”一列，写有“12月，占领南京，发生大屠杀事件”，并配有日军在南京盘查逃难中国百姓的照片。 然而，该馆7月28日公布的新展陈解说文本方案显示，有关“南京大屠杀”的表述从明年3月起将改为“南京事件”。管理核爆资料馆的长崎市政府竟宣称，这一改动是为了与日本官方表述及主流教科书“保持…"
