    "content": "新华社郑州8月16日电（记者马意翀、岳栋）经抢险救援人员持续奋战，8月15日晚，河南省周口市川汇区新北环桥下贾鲁河东岸堤防溃口成功合龙。 沙颍河畔，一条条粗壮的“水龙”顺着排水管“飞出”……8月16日清晨，在周口市七一路跨沙颍河大桥附近，来自多地的排水车、发电机、大功率水泵的轰鸣声响彻不停，一场与时间赛跑的城市排涝战正在紧锣密鼓地打响。 记者沿着周口市滨河北路旁边的堤坝一路前行，沙颍河的水位依然很高，但堤坝上的忙碌景象让人心安。 大型抽水泵开足马力，将城区积水源源不断地排入河道，身着橙色、蓝色等颜色制服的消防、应急…"
